<?php defined('ABSPATH') || exit; get_header(); while (have_posts()) { the_post(); ?>
<div class="container detail-section"><nav class="breadcrumbs" aria-label="Đường dẫn"><a href="<?php echo esc_url(home_url('/')); ?>">Trang chủ</a><span>/</span><a href="<?php echo esc_url(beautyglow_catalog_url()); ?>">Sản phẩm</a><span>/</span><span><?php the_title(); ?></span></nav>
<article class="product-detail"><div class="detail-photo"><?php if (has_post_thumbnail()) { the_post_thumbnail('large', array('fetchpriority' => 'high')); } else { ?><span class="image-placeholder"><span aria-hidden="true">✿</span>Chưa có ảnh sản phẩm</span><?php } ?></div>
<div class="detail-copy"><p class="eyebrow"><?php echo esc_html(get_post_meta(get_the_ID(), '_bg_brand', true)); ?></p><h1><?php the_title(); ?></h1><div class="detail-excerpt"><?php the_excerpt(); ?></div>
<dl class="product-facts"><?php foreach (array('brand' => 'Thương hiệu', 'code' => 'Mã sản phẩm', 'size' => 'Dung tích / khối lượng', 'variant' => 'Phiên bản / màu') as $key => $label) { $value = get_post_meta(get_the_ID(), '_bg_' . $key, true); if ($value !== '') { ?><div><dt><?php echo esc_html($label); ?></dt><dd><?php echo esc_html($value); ?></dd></div><?php } } ?>
<div><dt>Danh mục</dt><dd><?php echo wp_kses_post(get_the_term_list(get_the_ID(), 'bg_product_category', '', ', ')); ?></dd></div></dl>
<p class="detail-note">Thông tin mang tính tham khảo. Hãy đối chiếu phiên bản và hướng dẫn trên bao bì hoặc website của thương hiệu.</p><a class="text-link" href="<?php echo esc_url(beautyglow_catalog_url()); ?>">← Tiếp tục khám phá</a></div></article>
<section class="description-panel"><p class="eyebrow">TÌM HIỂU THÊM</p><h2>Thông tin sản phẩm</h2><div class="prose"><?php the_content(); ?></div><?php $source = get_post_meta(get_the_ID(), '_bg_information_source', true); if ($source) { ?><p><a class="text-link" href="<?php echo esc_url($source); ?>" target="_blank" rel="noopener noreferrer">Tham khảo thông tin từ thương hiệu ↗</a></p><?php } ?></section></div>
<?php } get_footer(); ?>
